//! Port of `lib/sandbox/SandboxedSpawn.java`.

use std::any::Any;
use std::io;

use blaze_shell::DescribableExecutionUnit;
use blaze_vfs::Path;

/// A description of a subprocess, as well as the necessary file system / sandbox setup.
///
/// Instances are responsible for making a list of input files available inside the sandbox root,
/// so that a process running inside the directory can access the files. It also handles moving the
/// output files generated by the process out of the directory into a destination directory.
///
/// Errors: `io::Error`; Java's `InterruptedException` is an `io::Error` made by
/// [`super::sandbox_helpers::interrupted_error`].
// Java: com/google/devtools/build/lib/sandbox/SandboxedSpawn.java:30 SandboxedSpawn
pub trait SandboxedSpawn: DescribableExecutionUnit + Send + Sync {
    /// The path in which to execute the subprocess.
    fn get_sandbox_exec_root(&self) -> &Path;

    /// Returns `true`, if the runner should use the Subprocess timeout feature.
    // Java: com/google/devtools/build/lib/sandbox/SandboxedSpawn.java:35 SandboxedSpawn.useSubprocessTimeout
    fn use_subprocess_timeout(&self) -> bool {
        false
    }

    /// Returns the path that sandbox debug output is written to, if any.
    fn get_sandbox_debug_path(&self) -> Option<&Path>;

    /// Returns the path where statistics about subprocess execution are written, if any.
    fn get_statistics_path(&self) -> Option<&Path>;

    /// Creates the sandboxed execution root, making all `inputs` available for reading, making
    /// sure that the parent directories of all `outputs` and that all `writableDirs` exist and
    /// can be written into.
    fn create_file_system(&self) -> io::Result<()>;

    /// Copies all `outputs` to `exec_root` while keeping the directory structure.
    ///
    /// An efficient implementation may move the files instead of copying them, if possible. It is
    /// unspecified whether the original files still exist after this method returns.
    fn copy_outputs(&self, exec_root: &Path) -> io::Result<()>;

    /// Deletes the sandbox directory.
    fn delete(&self);

    /// Returns user-facing instructions for starting an interactive sandboxed environment
    /// identical to the one in which this spawn is executed.
    // Java: com/google/devtools/build/lib/sandbox/SandboxedSpawn.java:73 SandboxedSpawn.getInteractiveDebugInstructions
    fn get_interactive_debug_instructions(&self) -> Option<String> {
        None
    }

    /// `instanceof` checks (tests).
    fn as_any(&self) -> &dyn Any;
}
